css:
/* Award badges: a centred heading over rows of shield-shaped badges, seven across. */
[data-bz-node="ab-band"] > .bz-container { max-width: calc(min(90vw, 1440px) + 32px); }
[data-bz-section="award-badges"] .bz-block { padding-block: 0; }
[data-bz-section="award-badges"] h2 { margin: 0; text-align: center; font: 700 1.5rem / 1.2 var(--font-heading); color: #000; letter-spacing: 0; }
[data-bz-section="award-badges"] [data-bz-node="ab-row"] { margin-top: 38px; display: grid; grid-template-columns: repeat(7, minmax(0, 1fr)); row-gap: 57px; justify-items: center; }
[data-bz-section="award-badges"] [data-bz-node="ab-row"] > .bz-col { grid-column: auto; width: min(180px, 92%); height: 259px; box-sizing: border-box; padding: 78px 16px 0; background: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 180 259' preserveAspectRatio='none'><path d='M3 8Q3 3 8 3H172Q177 3 177 8V208L90 256 3 208Z' fill='%23e9f6fe' stroke='%23b9dcf2' stroke-width='3'/></svg>") center / 100% 100% no-repeat; position: relative; text-align: center; }
[data-bz-section="award-badges"] [data-bz-node="ab-row"] > .bz-col::before { content: ""; position: absolute; left: 50%; top: 31px; width: 90px; height: 26px; margin-left: -45px; background: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 90 26'><path fill='%230090e4' d='M14.0,3.0 L16.5,9.6 L23.5,9.9 L18.0,14.3 L19.9,21.1 L14.0,17.2 L8.1,21.1 L10.0,14.3 L4.5,9.9 L11.5,9.6ZM45.0,-0.5 L48.1,7.8 L56.9,8.1 L50.0,13.6 L52.3,22.1 L45.0,17.2 L37.7,22.1 L40.0,13.6 L33.1,8.1 L41.9,7.8ZM76.0,3.0 L78.5,9.6 L85.5,9.9 L80.0,14.3 L81.9,21.1 L76.0,17.2 L70.1,21.1 L72.0,14.3 L66.5,9.9 L73.5,9.6Z'/></svg>") center / contain no-repeat; }
[data-bz-section="award-badges"] [data-bz-node="ab-row"] > .bz-col:nth-child(15) { grid-column: 2; }
[data-bz-section="award-badges"] [data-bz-node="ab-row"] > .bz-col:nth-child(17) { grid-column: 5; }
[data-bz-section="award-badges"] [data-bz-node^="ab-title"] .bz-text p { margin: 0; font: 700 0.68rem / 1.5 var(--font-heading); color: #000; max-width: none; }
[data-bz-section="award-badges"] [data-bz-node^="ab-accent"] .bz-text p { margin: 0; font: 700 0.68rem / 1.5 var(--font-heading); color: var(--accent); max-width: none; }
[data-bz-section="award-badges"] [data-bz-node^="ab-year"] .bz-text p { margin: 0; font: 700 0.68rem / 1.5 var(--font-heading); color: #000; max-width: none; }
@media (max-width: 1100px) { [data-bz-section="award-badges"] [data-bz-node="ab-row"] { grid-template-columns: repeat(4, minmax(0, 1fr)); } [data-bz-section="award-badges"] [data-bz-node="ab-row"] > .bz-col:nth-child(15), [data-bz-section="award-badges"] [data-bz-node="ab-row"] > .bz-col:nth-child(17) { grid-column: auto; } }
@media (max-width: 640px) { [data-bz-section="award-badges"] [data-bz-node="ab-row"] { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
